VALUES
  (gen_random_uuid(), 'CSC', 'CSC', 'Chinese Government Scholarship cho sinh viên quốc tế.', 'Thành tích học tập tốt, sức khỏe tốt, hồ sơ apply đầy đủ, ưu tiên HSK/IELTS theo chương trình.', 'Thường theo từng trường và kỳ tuyển sinh.', 'Có thể gồm học phí, ký túc xá, sinh hoạt phí và bảo hiểm tùy chương trình.', 'Nêu rõ mục tiêu học tập, kế hoạch nghiên cứu, lý do chọn Trung Quốc và đóng góp sau tốt nghiệp.', 'Phỏng vấn online/offline, hỏi động lực, chuyên ngành, study plan và khả năng thích nghi.', '["Why China?", "Why this university?", "Why this major?", "Tell us about your study plan.", "How will you contribute after graduation?"]'::jsonb, 'Trả lời cụ thể theo trường/ngành, tránh nói chung chung.', true, now(), now()),
  (gen_random_uuid(), 'Chinese Government Scholarship - Bilateral Program', 'CSC-BILATERAL', 'Học bổng chính phủ Trung Quốc theo hiệp định song phương.', 'Theo quy định cơ quan đề cử và trường tiếp nhận.', 'Theo thông báo đại sứ quán/cơ quan đề cử.', 'Thường hỗ trợ học phí, sinh hoạt phí, ký túc xá và bảo hiểm.', 'Nhấn mạnh vai trò cầu nối hợp tác Việt-Trung.', 'Có thể qua cơ quan đề cử hoặc trường.', '["Why are you a good bilateral candidate?", "How will your study support Vietnam-China cooperation?"]'::jsonb, 'Chuẩn bị câu chuyện đóng góp cộng đồng và hợp tác hai nước.', true, now(), now()),
  (gen_random_uuid(), 'Chinese Government Scholarship - University Program', 'CSC-UNIVERSITY', 'Học bổng CSC do trường đại học Trung Quốc tuyển chọn.', 'Hồ sơ học thuật mạnh, phù hợp ngành/lab/trường.', 'Theo deadline từng trường.', 'Tùy trường, thường là full scholarship.', 'Study plan cần fit với ngành, giáo sư, lab hoặc thế mạnh trường.', 'Trường phỏng vấn trực tiếp ứng viên.', '["Why our university?", "Which professor or lab interests you?", "What is your research plan?"]'::jsonb, 'Nêu rõ tên ngành/lab/thế mạnh trường.', true, now(), now()),
